    ) + InventoryRules.selectableCategories.flatMap { category ->
        (1..InventoryRules.INITIAL_ITEMS_PER_CATEGORY).map { index ->
            val key = category.lowercase().replace("á", "a").replace("ñ", "n")
                .replace(" ", "_")
            EquipmentDefinition(
                id = "${key}_seed_${index.toString().padStart(2, '0')}",
                slot = category,
                label = "$category Imperial ${index.toString().padStart(2, '0')}"
            )
        }
    }

    private val byId = entries.associateBy { it.id }
    val all: List<EquipmentDefinition> = entries

    fun definitionFor(id: String): EquipmentDefinition? = byId[id]

    fun statusLabel(id: String): String = when (byId[id]?.status) {
        EquipmentAssetStatus.MODEL_READY_LICENSE_REVIEW -> "EQUIPO 3D EN REVISIÓN"
        EquipmentAssetStatus.MODEL_PENDING, null -> "EQUIPO 3D PENDIENTE"
    }
}
